def insertion(a):
    a = list(a)
    for i in range(1, len(a)):
        x = a[i]
        j = i - 1
        while j >= 0 and a[j][0] > x[0]:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = x
    return a
def selection(a):
    a = list(a)
    for i in range(len(a)):
        m = min(range(i, len(a)), key=lambda k: (a[k][0], k))
        a[i], a[m] = a[m], a[i]
    return a
def merge(a):
    if len(a) <= 1:
        return list(a)
    mid = len(a) // 2
    l = merge(a[:mid])
    r = merge(a[mid:])
    out = []
    i = j = 0
    while i < len(l) and j < len(r):
        if l[i][0] <= r[j][0]:
            out.append(l[i])
            i += 1
        else:
            out.append(r[j])
            j += 1
    return out + l[i:] + r[j:]
def heap(a):
    a = list(a)
    n = len(a)
    def sift(i, n):
        while True:
            l = 2 * i + 1
            r = 2 * i + 2
            m = i
            if l < n and a[l][0] > a[m][0]:
                m = l
            if r < n and a[r][0] > a[m][0]:
                m = r
            if m == i:
                return
            a[i], a[m] = a[m], a[i]
            i = m
    for i in range(n // 2 - 1, -1, -1):
        sift(i, n)
    for end in range(n - 1, 0, -1):
        a[0], a[end] = a[end], a[0]
        sift(0, end)
    return a
